  async function uploadAsset(file){
    const allowed=new Set(['image/png','image/jpeg','image/webp']);
    if(!allowed.has(file?.type))throw new Error('Choose a PNG, JPG, or WebP image.');
    if(file.size>8*1024*1024)throw new Error('Choose an image smaller than 8 MB.');
    if(typeof globalThis.uploadVisualAsset!=='function')throw new Error('Sign in and connect cloud storage before uploading assets.');
    const result=await globalThis.uploadVisualAsset(file);
    if(!result?.url)throw new Error('The uploaded asset did not return a URL.');
    state.visualAssets=Array.isArray(state.visualAssets)?state.visualAssets:[];
    const asset={id:String(result.id||makeId('asset')),name:String(file.name),url:String(result.url),type:String(file.type),createdAt:Date.now()};
    state.visualAssets.push(asset);
    return asset;
  }
