  function applyEditorAction(action){const module=selected();if(action==='paste'&&editorClipboard){const copy=createModule(editorClipboard.type,{...JSON.parse(JSON.stringify(editorClipboard)),id:makeId('module'),name:`${editorClipboard.name||'Object'} copy`,x:(editorClipboard.x||0)+editorDraft.canvas.grid*2,y:(editorClipboard.y||0)+editorDraft.canvas.grid*2,locked:false,layer:editorDraft.modules.length});contain(editorDraft,copy);editorDraft.modules.push(copy);selectedModuleIds=new Set([copy.id]);return true;}if(!module)return false;if(action==='copy'){editorClipboard=JSON.parse(JSON.stringify(module));return true;}if(action==='duplicate'){const copy=duplicateModule(editorDraft,module.id);if(copy)selectedModuleIds=new Set([copy.id]);return Boolean(copy);}if(action==='delete'){deleteModule(editorDraft,module.id);selectedModuleIds.clear();return true;}if(action==='lock'){lockModule(editorDraft,module.id,!module.locked);return true;}if(action==='rotate-left'){module.rotation=snapRotation(module.rotation-90,{threshold:180});return true;}if(action==='rotate-right'){module.rotation=snapRotation(module.rotation+90,{threshold:180});return true;}if(action==='front'||action==='back'||action==='forward'||action==='backward'){layerModule(editorDraft,module.id,action);return true;}return false;}
  function editorContextMenuHtml(){const module=selected();if(!module||!editorContextMenu)return'';const actions=[['copy','Copy'],['paste','Paste'],['duplicate','Duplicate'],['delete','Delete'],['lock',module.locked?'Unlock':'Lock'],['rotate-left','Rotate left'],['rotate-right','Rotate right'],['front','Bring to front'],['back','Send to back']];return`<div class="builder-context-menu" data-builder-context-menu style="--menu-x:${number(editorContextMenu.x)}px;--menu-y:${number(editorContextMenu.y)}px" role="menu" aria-label="Object actions">${actions.map(([value,label])=>`<button type="button" role="menuitem" data-context-action="${value}" ${value==='paste'&&!editorClipboard?'disabled':''}>${label}</button>`).join('')}</div>`;}
