  function composerPanelHtml(){const regions=orderedRegions(editorDraft);return`<section class="composer-primary-controls"><h3>Card composition</h3><label>Card style<select data-composer-style>${['minimal','classic','dramatic','cozy','dark-academia','custom'].map(value=>`<option value="${value}" ${editorDraft.composer.stylePreset===value?'selected':''}>${value.replaceAll('-',' ')}</option>`).join('')}</select></label><label>Density<select data-composer-density>${[['compact','Compact'],['balanced','Balanced'],['expanded','Expanded']].map(([value,label])=>`<option value="${value}" ${editorDraft.composer.density===value?'selected':''}>${label}</option>`).join('')}</select></label><label>Typography<select data-composer-typography>${['elegant','modern','bold','compact'].map(value=>`<option ${editorDraft.composer.typography===value?'selected':''}>${value}</option>`).join('')}</select></label><div class="composer-region-list"><div class="composer-section-heading"><h3>Card regions</h3><button type="button" data-add-region>Add region</button></div>${regions.map((region,index)=>`<article class="composer-region ${region.collapsed?'is-collapsed':''}" data-region-id="${region.id}"><header><button type="button" data-toggle-region="${region.id}" aria-expanded="${!region.collapsed}">${region.collapsed?'▸':'▾'} ${escape(region.name)}</button><label><input type="checkbox" data-region-visible="${region.id}" ${region.visible!==false?'checked':''}> Show</label></header>${region.collapsed?'':`<p>${editorDraft.modules.filter(module=>module.groupId===region.id).length} modules · ${escape(region.role)}</p><div><button type="button" data-region-up="${region.id}" ${index===0?'disabled':''}>Move up</button><button type="button" data-region-down="${region.id}" ${index===regions.length-1?'disabled':''}>Move down</button></div>`}</article>`).join('')}</div></section>`;}
